def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return min(budget, 18.0)

    units = int(supply / WATER_REQ)
    if units < 1:
        units = 1

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    max_prev = 0.0
    for opp in alive:
        if opp.get('budget', 0) >= 250:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid > max_prev:
                    max_prev = bid

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    my_urgent = hp <= 3 or no_water_days >= 1
    very_urgent = hp <= 2 or no_water_days >= 2

    if units >= len(alive) + 1:
        base = 8.0
    elif units >= len(alive):
        base = 16.0
    elif units >= max(1, len(alive) - 1):
        base = 28.0
    else:
        base = 42.0

    pressure = 0.0
    if max_prev > 0:
        if max_prev >= 180:
            pressure += 18.0
        elif max_prev >= 100:
            pressure += 10.0
        elif max_prev >= 50:
            pressure += 5.0
    if avg_prev > 120:
        pressure += 6.0
    elif avg_prev > 60:
        pressure += 3.0

    pressure += urgent_opp * 4.0
    pressure += rich_opp * 2.0

    if my_urgent:
        pressure += 22.0
    if very_urgent:
        pressure += 18.0

    if day >= 8:
        pressure += 6.0

    target = base + pressure

    if prev_bids:
        if units <= max(1, len(alive) - 1):
            target = max(target, min(max_prev + 2.5, budget))
        elif my_urgent:
            target = max(target, min(max_prev + 1.0, budget))
        else:
            target = max(target, min(avg_prev * 0.45 + 3.0, budget))

    if units >= len(alive) + 1 and not my_urgent:
        target = min(target, 20.0)

    if budget < 60:
        target = min(target, max(12.0, budget * 0.72))
    elif budget < 120:
        target = min(target, budget * 0.68)
    else:
        target = min(target, budget * 0.52 + 12.0)

    if very_urgent:
        target = max(target, min(budget, max_prev + 5.0 if max_prev > 0 else 55.0))
    elif my_urgent:
        target = max(target, min(budget, max_prev + 2.0 if max_prev > 0 else 42.0))

    if hp >= 7 and no_water_days == 0 and units >= len(alive):
        target = min(target, 24.0)

    if target < 0:
        target = 0.0
    if target > budget:
        target = budget

    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    if not alive:
        return min(budget, DAILY_SALARY * 0.4)

    # Immediate reaction from yesterday trace only
    yesterday_bids = []
    yesterday_hp_after = []
    for o in alive:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass
            try:
                yesterday_hp_after.append(float(prev.get('hp_after')))
            except Exception:
                pass

    if not yesterday_bids:
        # Default: moderate pressure
        base = DAILY_SALARY * 0.55
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.9
        return min(budget, base)

    highest_prev_bid = max(yesterday_bids)
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid

    # Estimate how costly it is to win: bid slightly above the upper competitive band
    # Cindy's behavior suggests high willingness to pay; Eric suggests sometimes she overpays.
    competitive_band = max(second_prev_bid, highest_prev_bid * 0.75)

    # If opponent(s) were extremely aggressive, we must decide whether to contest hard.
    # Preserve budget unless we are in danger.
    danger = (hp <= 2) or (no_water_days >= 2)
    low_budget = budget <= DAILY_SALARY * 1.0

    if highest_prev_bid >= DAILY_SALARY * 1.6:
        # Very aggressive yesterday: either contest slightly or conserve if in danger.
        if danger or low_budget:
            bid = min(budget, DAILY_SALARY * 0.95)
        else:
            bid = min(budget, max(competitive_band + 5.0, DAILY_SALARY * 0.7))
    else:
        # Moderate yesterday: bid just above the likely winner.
        if danger:
            bid = min(budget, max(competitive_band + 3.0, DAILY_SALARY * 0.85))
        else:
            bid = min(budget, max(competitive_band + 2.0, DAILY_SALARY * 0.55))

    # Supply-based adjustment: if supply is high, winning is cheaper; if low, we need more certainty.
    # supply is between 15 and 25.
    if supply <= 17.0:
        bid *= 1.08
    elif supply >= 22.0:
        bid *= 0.95

    # Final safety clamps
    bid = float(bid)
    if bid < 0:
        bid = 0.0
    if budget <= 0:
        return 0.0

    return min(budget, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = 0
    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)

    # --- Bidding Strategy ---

    # Critical HP or missed water yesterday: Bid aggressively
    if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 0.95 # High bid to ensure water
        if max_yesterday_bid > 0:
            bid = max(bid, max_yesterday_bid * 1.05) # Outbid previous high if necessary
        return min(my_status['budget'], bid)

    # End of the episode: Increase urgency
    if day_context['day'] >= EPISODE_DAYS - 2: # Last two days
        bid = DAILY_SALARY * 0.8
        if max_yesterday_bid > 0:
            bid = max(bid, max_yesterday_bid * 1.03) # Slightly outbid
        return min(my_status['budget'], bid)

    # Normal state bidding
    base_bid = DAILY_SALARY * 0.55

    # Adjust based on supply: lower supply means higher competition
    if day_context['supply'] <= 18: # Low supply
        base_bid *= 1.15
    elif day_context['supply'] >= 22: # High supply
        base_bid *= 0.9

    # Adjust based on yesterday's highest bid
    if max_yesterday_bid > 0:
        if max_yesterday_bid > DAILY_SALARY * 0.7: # If opponents bid high yesterday
            base_bid = max(base_bid, max_yesterday_bid * 1.01) # Try to slightly outbid
        elif max_yesterday_bid < DAILY_SALARY * 0.4: # If opponents bid low yesterday
            base_bid = min(base_bid, max_yesterday_bid * 1.1) # Don't overpay too much

    # Consider number of alive opponents: more opponents, more competition
    if num_alive_opponents >= 3:
        base_bid *= 1.05
    elif num_alive_opponents == 1:
        base_bid *= 0.95

    # Ensure a minimum bid to stay competitive
    final_bid = max(DAILY_SALARY * 0.2, base_bid)

    return min(my_status['budget'], final_bid)
